INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(281700, 0, 2817, 0, 0, 13, 'Crystalsong Forest', 'Crystalsong Forest lies at the heart of Northrend, hemmed in by the Dragonblight to the south, Zul''Drak to the east, and Icecrown and the Storm Peaks to the north. Its trees are crystal from root to leaf, and its woods glitter in shades of gold and russet. In ages past night elves dwelt here at Shandaral, and the ruins of their home still stand. Their spirits have never left: lost spirits roam the western woods, and in the ruins the dead still take up arms against every intruder. In the east, strange beings steeped in magic, called the Unbound, haunt the thicket. Above the western woods floats Dalaran, and on the ground beneath it the Kirin Tor hold the Violet Stand, while servants of the blue dragonflight have dug in close by at the Azure Front. Farther east, the Silver Covenant and the Sunreavers each keep a camp of their own, facing one another across the old ruins.', 'warcraft.wiki.gg/wiki/Crystalsong_Forest (borders, Violet Stand under Dalaran, Azure Front, the two camps; later and RPG material left out); DB spawns grouped by subzone (copy of zone_areas.py with Dalaran''s floating spawns removed): Shandaral spirits 30863-30865, 31231 in 4553/4554/4557; Unbound 30856, 30860-30862, 30868, 33422; Kirin Tor at 4556; azure dragonkin at 4555; Silver Covenant at 4559, Sunreavers at 4558; quest 13641 description (night elf ruins in the Forlorn Woods); quests 12791/12794 descriptions and dalaran.json 439500 (Dalaran floats above the forest)'),
(281701, 1, 2817, 1, 0, 13, 'The Violet Stand', 'The Violet Stand is the Kirin Tor''s foothold on the forest floor, set among old elven ruins in the west of the woods, beneath the edge of Dalaran. Gatekeeper Melindra and Librarian Belleford are posted here. The warmages Sarina, Halister and Ilsudria stand fixed at their posts, channeling their power without rest into the shield that guards the outpost, and Warmage Yurias stands ready beside them. The guard is not for show: blue dragonkin of the nearby Azure Front prowl at the stand''s very edge. A crystal here carries travelers up to the city above.', 'zone script zone_crystalsong_forest.cpp npc_warmage_violetstand (Sarina, Halister, Ilsudria channel Transitus Shield Beam 48310 at the shield orbs 27306 and never move); DB spawns in 4556: Melindra 32373, Belleford 32374, Sarina 32369, Halister 32371, Ilsudria 32372, Yurias 32375 (faction 2009), Transitus Shield Invisible Bunny 27306 x3, Azure Scalebane 31402 x3, gameobject 191230 Teleport to Dalaran Crystal; npc_text 13455/13456 (Celindra: the crystal teleports to the ruins below Dalaran); warcraft.wiki.gg/wiki/Violet_Stand (Kirin Tor outpost within night elf ruins, shield dome against the blue dragonflight)'),
(281702, 1, 2817, 2, 0, 13, 'The Twilight Rivulet', 'The Twilight Rivulet winds through the Forlorn Woods in the shadow of floating Dalaran. It rises in the northwest at the Decrepit Flow, where ice spills down into the forest from the Ironwall Dam on the border of Icecrown, and runs south to a pool called the Mirror of Twilight. Schools of glassfin minnows dart through its clear water, and Crystalsong carrots grow wild along its banks. Dalaran''s cooks send for them when the inn beneath the city runs short of food.', 'quest 13600 description (ice flowing from the Ironwall Dam on Crystalsong''s northwestern border with Icecrown); warcraft.wiki.gg/wiki/Forlorn_Woods (the Twilight Rivulet runs from the Decrepit Flow to the Mirror of Twilight beneath Dalaran); DB: Glassfin Minnow School 192059 in 4550/4551, Crystalsong Carrot 192828 in 4551; quests 13102/13114 descriptions (Dalaran''s cooks gather Crystalsong carrots for a stew); posarea grid scan: 4552 at x 6100-6300 y 800-1160 (northwest), 4551 x 5500-6060 under Dalaran, 4550 x 5460-5500 y 80-160'),
(281703, 1, 2817, 3, 0, 13, 'The Azure Front', 'Southeast of the Violet Stand, the blue dragonflight holds the Azure Front, its foothold on the ground against Dalaran and the Kirin Tor in the war Malygos wages over the world''s magic. Azure manashapers labor among the crystal trees, scalebanes and spellweavers stand guard with mana-hungry beasts at their heels, and crystal wyrms circle high above. Beams of light run from tree to tree, and foci of azure crystal are set among the trunks, as though the dragons mean to draw on whatever power the forest holds.', 'DB spawns in 4555: Azure Manashaper 31401 x12 (work emote), Azure Scalebane 31402, Azure Spellweaver 31403, Azure Manabeast 31404 (Mana Bite), Crystal Wyrm 31393 (elite, z 315-322), Azure Front Channel Stalker 31400 casting ''Cosmetic - Crystalsong Tree Beam'' 59044 from stalker to stalker (smart_scripts -111726, -111742, -111746, -203457), gameobjects Azure Focus 193202 x3 and Uncut Azure Focus 193214; warcraft.wiki.gg/wiki/The_Azure_Front (a front against Dalaran and the Kirin Tor; the flight draws power from the crystal trees)'),
(281704, 1, 2817, 4, 0, 13, 'The Forlorn Woods', 'The Forlorn Woods fill the western heart of the forest, their crystal boughs tinted gold and russet as if caught forever in autumn. Wolves and dappled stags roam between the trunks, grove walkers and great ancient watchers stand among the trees, and dispirited ents move among them. The lost spirits of Shandaral wander here as well, and lonely elven ruins dot the woods. Near those ruins in the center of the forest gather the unbound seers, who turn on anyone who comes too close.', 'DB spawns in 4553: Sinewy Wolf 31233, Dappled Stag 31236, Grove Walker 31228, Ancient Watcher 31229 (elite), Dispirited Ent 31041, Lost Shandaral Spirit 31231 (faction template 14, hostile to players), Unbound Seer 33422 x9 (faction 16, hostile; x 5727-5812, y 124-249); quest 13641 description (unbound seers congregate near night elf ruins in the Forlorn Woods in the central part of the forest); warcraft.wiki.gg/wiki/Forlorn_Woods (western half, autumn colors, lonely elf ruins)'),
(281705, 1, 2817, 5, 0, 13, 'Ruins of Shandaral', 'The Ruins of Shandaral lie in the east of the forest, between the camps of the Silver Covenant and the Sunreavers: broken walls and fallen stonework of a night elf settlement from ages past. Its people have never left. Their spirits still keep watch, warriors with shields, druids, and hunters with spectral wolves at their side, and they strike at every living intruder as though the town still needed defending. Unbound corrupters and tricksters prowl the ruins among unbound ents and dryads, and blocks of ancient elven masonry lie scattered across the ground.', 'DB spawns in 4554: Shandaral Warrior Spirit 30865 (Shield Bash), Druid Spirit 30863, Hunter Spirit 30864, Shandaral Spirit Wolf 31123 (all faction 16, hostile), Unbound Corrupter 30868, Trickster 30856, Ent 30862, Dryad 30860, Ancient Elven Masonry 192909-192912; quest 13130 description (elven masonry from the Ruins of Shandaral); warcraft.wiki.gg/wiki/Windrunner''s_Overlook (across the Ruins of Shandaral from Sunreaver''s Command); posarea grid scan: 4554 at x 5260-5460, between 4559 (x 5040) and 4558 (x 5620)'),
(281706, 1, 2817, 6, 0, 13, 'The Unbound Thicket', 'The Unbound Thicket covers the eastern half of Crystalsong Forest. It takes its name from the Unbound who haunt it: tricksters and corrupters armed with fire and arcane curses, dryads who hurl spears, ents whose healing magic has turned corrupt, and towering ancients. Every creature of the thicket shares an affinity for magic, and each is said to hold a core of crystallized energy. Dispirited ents wander among their unbound kin, spirits of Shandaral stray out of the ruins, and trunks of crystalline heartwood lie on the thicket floor.', 'DB spawns in 4557: Unbound Ent 30862 (Corrupted Rejuvenation 58624), Unbound Dryad 30860 (Throw Spear), Unbound Trickster 30856 (Fire Blast), Unbound Corrupter 30868 (Arcane Bolt, Ley Curse), Unbound Ancient 30861 (elite; Entangling Roots, Trample), Dispirited Ent 31041 (faction template 14, hostile), Shandaral Hunter, Druid and Warrior Spirits 30863-30865, Crystalline Heartwood 192908 x27; quest 13135 description (the thicket''s creatures share an affinity for magical energy; each holds pure, crystallized energy); warcraft.wiki.gg/wiki/Unbound_Thicket (eastern half)'),
(281707, 1, 2817, 7, 0, 13, 'Windrunner''s Overlook', 'Windrunner''s Overlook is the Silver Covenant''s camp in Crystalsong Forest, raised around an old elven tower on the southern edge of the Unbound Thicket. It bears the name of the Windrunners, the house of the Covenant''s Ranger General, Vereesa. Scout Captain Daelin commands here. His scouts and mounted horsemen patrol the camp and the thicket around it, and Galendror Whitewing keeps the hippogryphs that carry the Covenant''s riders through the north. The high elves stock a smith''s supplies, food and drink, and poisons and reagents, but the Overlook is a soldiers'' post first, keeping watch across the ruins toward the Sunreavers.', 'DB spawns in 4559: Scout Captain Daelin 30261, Silver Covenant Scout 30238 (also in 4557), Horseman 30263, Hippogryph 30281, Galendror Whitewing 30271 (Hippogryph Master), Lanudal Silverhart 30241, Miura Brightweaver 30244, Aniduria 30255, Scout Yribria 30257; warcraft.wiki.gg/wiki/Windrunner''s_Overlook (Silver Covenant outpost, Daelin, no quests); warcraft.wiki.gg/wiki/Crystalsong_Forest (the camps hold two ruined elven towers); dalaran.json 439521 (Vereesa, Ranger General of the Silver Covenant)'),
(281708, 1, 2817, 8, 0, 13, 'Sunreaver''s Command', 'Sunreaver''s Command is the camp of the Sunreavers, the blood elves who follow Archmage Aethas Sunreaver, on the northern edge of the Unbound Thicket. Like the Silver Covenant''s overlook to the south, it is raised around an old elven tower, and the two camps face each other across the thicket and the Ruins of Shandaral. Scout Captain Elsia commands here. Her scouts guard the camp, mounted hawkriders keep watch, and Skymaster Baeric tends the dragonhawks that carry Sunreaver riders across the north. Sellers of food, smithing goods, poisons and reagents keep the post supplied.', 'DB spawns in 4558: Scout Captain Elsia 30259, Sunreaver Scout 30233, Sunreaver Hawkrider 30265, Sunreaver Dragonhawk 30290, Skymaster Baeric 30269 (Dragonhawk Master), Alanura Firecloud 30239, Felindel Sunhammer 30253, Marisalira 30254, Scout Ordimbral 30256; warcraft.wiki.gg/wiki/Sunreaver''s_Command (Sunreaver outpost, Elsia, opposite Windrunner''s Overlook, no quests); warcraft.wiki.gg/wiki/Crystalsong_Forest (the camps hold two ruined elven towers); dalaran.json 439522 (Aethas Sunreaver and his followers)'),
(281720, 2, 2817, 1, 0, 14, 'Lord Everblaze', 'Lord Everblaze is a lord of living fire who has taken his perch on a lofty crag in the south of Crystalsong Forest, looking down over the mouth of the Crystal Vice in the Dragonblight. Fiery dancers circle him in a ring of flame, strange company among the cold crystal trees, and the height of his crag keeps him beyond the reach of anyone who cannot fly. What brought a creature of fire to this frozen forest, no one has said.', 'creature 33289 Lord Everblaze (type elemental, one spawn at 5143,-76, z 347, posarea 2817), Fiery Dancer 33291 x12 around him (faction 35); quest 13616 description (southern Crystalsong Forest, overlooking the Crystal Vice''s exit); warcraft.wiki.gg/wiki/Lord_Everblaze (fire revenant, reachable only by flying, added in patch 3.1.0)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(281702, 1, 15, 255, 'Winter hyacinths grow nowhere but on the ice spilling down from the Ironwall Dam, and the Decrepit Flow is where that ice reaches the forest. Wandering bards tell of travelers who once carried these flowers to a lonely maiden at Drak''Mar Lake in the Dragonblight and were given gifts in return, and champions of the Argent Tournament in need of a blade now send for them again.', 'quests 13600, 13669, 13674, 13742, 13747, 13753, 13758, 13763, 13769, 13774, 13779, 13784 descriptions and request text (hyacinths grow only on the ice flowing from the Ironwall Dam; the bards'' tale of the lonely maiden; Drak''Mar Lake; the wandering bard''s tales); gameobject 194213 Winter Hyacinth: 4 spawns in 4552, 8 in Ironwall Dam 4503 (Icecrown)'),
(281720, 1, 15, 255, 'Champions of the Argent Tournament in need of a blade have found a use for him. They send fighters up to his crag to slay him for his everburning ember, which can free a maiden encased in ice far away at Winter''s Breath Lake in the Howling Fjord, the guardian of an ancient sword.', 'quests 13616, 13670, 13675, 13743, 13748, 13754, 13759, 13764, 13770, 13775, 13780, 13785 descriptions and reward text (Lord Everblaze in southern Crystalsong overlooking the Crystal Vice''s exit; the everburning ember frees the maiden encased in ice at Winter''s Breath Lake; she guards Winter''s Edge)');
